<?php
use App\Actions\Donations\SubmitPublicDonation; use App\DonationPaymentMethod; use App\Models\DonationCampaign; use App\Models\DonationCategory; use App\Settings\SettingManager; use Illuminate\Support\Facades\RateLimiter; use Illuminate\Support\Str; use Illuminate\Validation\Rule; use Illuminate\Validation\ValidationException; use Livewire\Attributes\Layout; use Livewire\Attributes\Title; use Livewire\Component;
new #[Layout('layouts.public'),Title('Give')] class extends Component { public string $firstName=''; public string $lastName=''; public string $email=''; public string $phone=''; public bool $anonymous=false; public string $categoryId=''; public string $campaignId=''; public string $amount=''; public string $method='bank_transfer'; public string $notes=''; public bool $consent=false; public string $website=''; public int $startedAt; public string $submissionKey; public ?string $successReference=null; /** @var array<string,mixed> */ public array $settings=[];
 public function mount(SettingManager $settings):void{$this->settings=$settings->publicGroup('donations');abort_unless((bool)data_get($this->settings,'enabled',true),404);$this->startedAt=now()->timestamp;$this->submissionKey=(string)Str::uuid();}
 public function submit(SubmitPublicDonation $submit):void{if($this->website!==''||now()->timestamp-$this->startedAt<3)throw ValidationException::withMessages(['amount'=>__('Please review the form and try again.')]);$minimum=(float)data_get($this->settings,'minimum_amount',1);$v=$this->validate(['firstName'=>[Rule::requiredIf(!$this->anonymous),'nullable','string','max:100'],'lastName'=>['nullable','string','max:100'],'email'=>[Rule::requiredIf((bool)data_get($this->settings,'require_email',true)&&!$this->anonymous),'nullable','email','max:255'],'phone'=>[Rule::requiredIf((bool)data_get($this->settings,'require_phone',false)&&!$this->anonymous),'nullable','string','max:50'],'categoryId'=>['required','exists:donation_categories,id'],'campaignId'=>['nullable','exists:donation_campaigns,id'],'amount'=>['required','numeric','min:'.$minimum],'method'=>['required',Rule::in([DonationPaymentMethod::BankTransfer->value,DonationPaymentMethod::MobileMoney->value,DonationPaymentMethod::Cheque->value,DonationPaymentMethod::Other->value])],'notes'=>['nullable','string','max:1000'],'consent'=>['accepted']]);$category=DonationCategory::whereKey($v['categoryId'])->where('is_active',true)->where('display_on_website',true)->firstOrFail();if($v['campaignId'])DonationCampaign::whereKey($v['campaignId'])->where('status','active')->where('display_on_website',true)->firstOrFail();$key='give:'.hash('sha256',(string)request()->ip());if(RateLimiter::tooManyAttempts($key,5))throw ValidationException::withMessages(['amount'=>__('Too many submissions. Please try again later.')]);$donation=$submit->handle(['first_name'=>$v['firstName']?:'','last_name'=>$v['lastName']?:'','email'=>$v['email']?:null,'phone'=>$v['phone']?:null,'is_anonymous'=>$this->anonymous,'donation_category_id'=>$category->id,'donation_campaign_id'=>$v['campaignId']?:null,'amount'=>$v['amount'],'currency'=>(string)app(SettingManager::class)->get('localization','default_currency','USD'),'payment_method'=>$v['method'],'notes'=>$v['notes']?:null,'submission_key'=>$this->submissionKey]);RateLimiter::increment($key,decaySeconds:3600);$this->successReference=$donation->reference;$this->reset(['firstName','lastName','email','phone','anonymous','categoryId','campaignId','amount','notes','consent']);$this->submissionKey=(string)Str::uuid();$this->startedAt=now()->timestamp;}
 public function categories(){return DonationCategory::where('is_active',true)->where('display_on_website',true)->orderBy('sort_order')->get();} public function campaigns(){return DonationCampaign::withSum(['donations as raised'=>fn($q)=>$q->completed()],'amount')->where('status','active')->where('display_on_website',true)->orderByDesc('is_featured')->get();}
